# -*- coding: utf-8 -*-
"""Formatting only: all meanings, labels and relationships below are authored decisions."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
LIMITS=["仅处理已提供的访谈转写全文；未核听录音，未独立验证银行、平台或产品事实。", "当前精确模型ID、采样参数和预算均为unknown，继承当前模型配置；生成方自检不构成独立审查或形式证明。", "原契约无独立障碍、偏好与贡献关联层；关键条件以目标context、推断和问题承接，人审pending。"]

def goal(doc,n,statement,origin,label,turn,quote,reason,context=None,assumptions=None,extra=None):
    # origin and label are both supplied by the author, never mapped by this formatter.
    a=assumptions or []
    return dict(candidate_id=f"{doc}-G{n:02}",statement=statement,origin=origin,actor="受访者",context=context or [],
      inference=None if origin=="explicit" else dict(basis_candidate_ids=[],reason=reason,assumptions=a),
      evidence=[dict(source_id=f"{doc}:T{turn:03}",quote=quote)]+(extra or []),
      support=dict(label=label,rationale=reason,supported_parts=[statement] if label in ("direct","inferred") else [],unsupported_parts=[] if label in ("direct","inferred") else ["当前表述仍待补证"],assumptions=a,reasoning_steps=[reason]))

def ev(doc,t,q): return dict(source_id=f"{doc}:T{t:03}",quote=q)

def save(doc,goals,groups,questions,model_questions,analysis):
    review=f"# {doc} 生成方语义自检\n\n完整读取该文档提供的全部访谈轮次（包括采访者问题、回答、后续解释及例外），未读取参考答案或其他文档产物。实际来源是已处理文本，未核听录音、未外部验证产品事实。\n\n## 逐目标核验\n\n"
    for g in goals:
        review+=f"- {g['candidate_id']}：{g['statement']}。origin={g['origin']}；support={g['support']['label']}。{g['support']['rationale']} 条件：{'；'.join(g['context']) or '无另加条件'}。\n"
    review+="\n## 精化、覆盖与场景检查\n\n"+analysis+"\n\n所有精化候选逐组复核，未将程序检查等同语义证明。下述inspect与finalize由冻结脚本实际执行，结果以inspection.json和run-record.json为准。独立语义审查not_run，形式证明not_run，人工审核pending。无新证据不能解决的问题保留待审，不循环推测补齐。\n"
    data=dict(document_id=doc,status="completed",limitations=LIMITS,goals=goals,groups=groups,review_questions=questions,model_questions=model_questions,author_review=review)
    dest=ROOT/'revised'/'_authoring'/f'{doc}.json'
    dest.parent.mkdir(parents=True,exist_ok=True)
    with dest.open('x',encoding='utf-8') as f: json.dump(data,f,ensure_ascii=False,indent=2)

def rq(ids,q,r): return dict(candidate_ids=ids,question=q,reason=r)
def mq(doc,q): return dict(target_type="model",target_id=f"{doc}-goal-model",message=q)

